{"command":"cat << 'EOF' > /tmp/test_checkers.py
import subprocess, os

test_cases = [
    ("assignOp", "x = x + 1", """
package main
func main() {
    x := 1
    x = x + 1
}
"""),
    ("captLocal", "Var inside func", """
package main
func main() {
    var LocalVar int
    _ = LocalVar
}
"""),
    ("commentFormatting", "no space comment", """
package main
//bad comment
func main() {}
"""),
    ("defaultCaseOrder", "default middle case", """
package main
func main() {
    x := 1
    switch x {
    case 1:
    default:
    case 2:
    }
}
"""),
    ("dupArg", "dup arg call", """
package main
import "bytes"
func main() {
    var b []byte
    _ = bytes.Equal(b, b)
}
"""),
    ("dupBranchBody", "dup branch", """
package main
import "fmt"
func main() {
    x := 1
    if x == 1 {
        fmt.Println("hi")
    } else {
        fmt.Println("hi")
    }
}
"""),
    ("dupCase", "dup case in switch", """
package main
func main() {
    x := 1
    switch x {
    case 1:
    case 1:
    }
}
"""),
    ("dupSubExpr", "dup subexpr in binop", """
package main
func main() {
    x := 1
    _ = x == x
}
"""),
    ("elseif", "else if simplification", """
package main
func main() {
    x := 1
    if x == 1 {
    } else {
        if x == 2 {
        }
    }
}
"""),
    ("exitAfterDefer", "exit after defer", """
package main
import "os"
func main() {
    defer func() {}()
    os.Exit(1)
}
"""),
    ("newDeref", "new deref", """
package main
func main() {
    _ = *new(int)
}
"""),
    ("singleCaseSwitch", "single case switch", """
package main
func main() {
    x := 1
    switch x {
    case 1:
    }
}
"""),
    ("sloppyLen", "sloppy len", """
package main
func main() {
    var s []int
    _ = len(s) >= 0
}
"""),
    ("underef", "underef field", """
package main
type S struct{ f int }
func main() {
    var s *S
    _ = (*s).f
