{"command":"cat << 'EOF' > /workspace/checkers.go
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/token"
	"go/types"
	"path/filepath"
	"regexp"
	"strings"
)

type Warning struct {
	FilePath string
	Line     int
	Column   int
	Checker  string
	Message  string
}

type CheckContext struct {
	Fset                      *token.FileSet
	File                      *ast.File
	FilePath                  string
	TypeInfo                  *types.Info
	CaptLocalParamsOnly       bool
	CommentedOutCodeMinLength int
	ElseifSkipBalanced        bool
	HugeParamSizeThreshold    int
	IfElseChainMinThreshold   int
	NestingReduceBodyWidth    int
	RangeExprCopySizeThreshold int
	RangeValCopySizeThreshold int
	RangeExprCopySkipTestFuncs bool
	RangeValCopySkipTestFuncs bool
}

type CheckerFunc func(ctx *CheckContext) []Warning

var checkerRegistry = map[string]CheckerFunc{
	"appendAssign":     checkAppendAssign,
	"argOrder":         checkArgOrder,
	"assignOp":         checkAssignOp,
	"badCall":          checkBadCall,
	"badCond":          checkBadCond,
	"captLocal":        checkCaptLocal,
	"caseOrder":        checkCaseOrder,
	"commentFormatting": checkCommentFormatting,
	"defaultCaseOrder": checkDefaultCaseOrder,
	"deprecatedComment": checkDeprecatedComment,
	"dupArg":           checkDupArg,
	"dupBranchBody":    checkDupBranchBody,
	"dupCase":          checkDupCase,
	"dupSubExpr":       checkDupSubExpr,
	"elseif":           checkElseif,
	"exitAfterDefer":   checkExitAfterDefer,
	"flagDeref":        checkFlagDeref,
	"flagName":         checkFlagName,
	"ifElseChain":      checkIfElseChain,
	"mapKey":           checkMapKey,
	"newDeref":         checkNewDeref,
	"offBy1":           checkOffBy1,
	"rangeExprCopy":    checkRangeExprCopy,
	"singleCaseSwitch": checkSingleCaseSwitch,
	"sloppyLen":        checkSloppyLen,
	"switchTrue":       checkSwitchTrue,
	"underef":          checkUnderef,
	"unlambda":         checkUnlambda,
	"unslice":          checkUnslice,
	"valSwap":          checkValSwap,
	"wrapperFunc":      checkWrapperFunc,
}

func renderNode(fset *token.FileSet, n interface{}) string {
	var buf bytes.Buffer
	if err := format.Node(&buf, fset, n); err != nil {
		return ""
	}
	return buf.String()
}

func equalExpr(a, b ast.Expr) bool {
	if a == nil || b == nil {
		return a == b
	}
	switch x := a.(type) {
	case *ast.Ident:
		y, ok := b.(*ast.Ident)
		return ok && x.Name == y.Name
	case *ast.BasicLit:
		y, ok := b.(*ast.BasicLit)
		return ok && x.Kind == y.Kind && x.Value == y.Value
	case *ast.SelectorExpr:
		y, ok := b.(*ast.SelectorExpr)
		return ok && x.Sel.Name == y.Sel.Name && equalExpr(x.X, y.X)
	case *ast.IndexExpr:
		y, ok := b.(*ast.IndexExpr)
		return ok && equalExpr(x.X, y.X) && equalExpr(x.Index, y.Index)
	case *ast.StarExpr:
		y, ok := b.(*ast.StarExpr)
		return ok && equalExpr(x.X, y.X)
	case *ast.UnaryExpr:
		y, ok := b.(*ast.UnaryExpr)
		return ok && x.Op == y.Op && equalExpr(x.X, y.X)
	case *ast.BinaryExpr:
		y, ok := b.(*ast.BinaryExpr)
		return ok && x.Op == y.Op && equalExpr(x.X, y.X) && equalExpr(x.Y, y.Y)
	case *ast.CallExpr:
		y, ok := b.(*ast.CallExpr)
		if !ok || len(x.Args) != len(y.Args) || !equalExpr(x.Fun, y.Fun) {
			return false
		}
		for i := range x.Args {
			if !equalExpr(x.Args[i], y.Args[i]) {
				return false
			}
		}
		return true
	case *ast.ParenExpr:
		return equalExpr(x.X, b)
	}
	return false
}

func addWarn(ctx *CheckContext, pos token.Pos, checker, msg string) Warning {
	position := ctx.Fset.Position(pos)
	return Warning{
		FilePath: ctx.FilePath,
		Line:     position.Line,
		Column:   position.Column,
		Checker:  checker,
		Message:  msg,
	}
}

func checkAppendAssign(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		stmt, ok := n.(*ast.AssignStmt)
		if !ok || len(stmt.Lhs) != 1 || len(stmt.Rhs) != 1 {
			return true
		}
		call, ok := stmt.Rhs[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		ident, ok := call.Fun.(*ast.Ident)
		if !ok || ident.Name != "append" || len(call.Args) == 0 {
			return true
		}
		if !equalExpr(stmt.Lhs[0], call.Args[0]) {
			warnings = append(warnings, addWarn(ctx, call.Pos(), "appendAssign", "append result not assigned to the same slice"))
		}
		return true
	})
	return warnings
}

func checkArgOrder(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 2 {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		pkgIdent, ok := sel.X.(*ast.Ident)
		if !ok || pkgIdent.Name != "strings" {
			return true
		}
		fn := sel.Sel.Name
		if fn == "HasPrefix" || fn == "HasSuffix" || fn == "Contains" {
			_, firstLit := call.Args[0].(*ast.BasicLit)
			_, secondLit := call.Args[1].(*ast.BasicLit)
			if firstLit && !secondLit {
				arg0 := renderNode(ctx.Fset, call.Args[0])
				arg1 := renderNode(ctx.Fset, call.Args[1])
				warnings = append(warnings, addWarn(ctx, call.Pos(), "argOrder", fmt.Sprintf("%s and %s arguments order looks reversed", arg0, arg1)))
			}
		}
		return true
	})
	return warnings
}

func checkAssignOp(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		stmt, ok := n.(*ast.AssignStmt)
		if !ok || stmt.Tok != token.ASSIGN || len(stmt.Lhs) != 1 || len(stmt.Rhs) != 1 {
			return true
		}
		bin, ok := stmt.Rhs[0].(*ast.BinaryExpr)
		if !ok {
			return true
		}
		if equalExpr(stmt.Lhs[0], bin.X) {
			xStr := renderNode(ctx.Fset, stmt.Lhs[0])
			yStr := renderNode(ctx.Fset, bin.Y)
			if bin.Op == token.ADD && yStr == "1" {
				warnings = append(warnings, addWarn(ctx, stmt.Pos(), "assignOp", fmt.Sprintf("replace `%s = %s + 1` with `%s++`", xStr, xStr, xStr)))
			} else {
				opStr := bin.Op.String()
				warnings = append(warnings, addWarn(ctx, stmt.Pos(), "assignOp", fmt.Sprintf("replace `%s = %s %s %s` with `%s %s= %s`", xStr, xStr, opStr, yStr, xStr, opStr, yStr)))
			}
		}
		return true
	})
	return warnings
}

func checkBadCall(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 4 {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		pkgIdent, ok := sel.X.(*ast.Ident)
		if !ok || (pkgIdent.Name != "strings" && pkgIdent.Name != "bytes") {
			return true
		}
		if sel.Sel.Name == "Replace" {
			if lit, ok := call.Args[3].(*ast.BasicLit); ok && lit.Value == "0" {
				position := ctx.Fset.Position(call.Args[3].Pos())
				warnings = append(warnings, Warning{
					FilePath: ctx.FilePath,
					Line:     position.Line,
					Column:   position.Column,
					Checker:  "badCall",
					Message:  "suspicious arg 0, probably meant -1",
				})
			}
		}
		return true
	})
	return warnings
}

func checkBadCond(ctx *CheckContext) []Warning {
	var warnings []Warning
	return warnings
}

func checkCaptLocal(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Type == nil {
			return true
		}
		checkFieldList := func(fields *ast.FieldList) {
			if fields == nil {
				return
			}
			for _, field := range fields.List {
				for _, name := range field.Names {
					if name.Name != "" && name.Name[0] >= 'A' && name.Name[0] <= 'Z' {
						warnings = append(warnings, addWarn(ctx, name.Pos(), "captLocal", fmt.Sprintf("`%s' should not be capitalized", name.Name)))
					}
				}
			}
		}
		checkFieldList(fn.Type.Params)
		checkFieldList(fn.Type.Results)
		return true
	})
	return warnings
}

func checkCaseOrder(ctx *CheckContext) []Warning {
	var warnings []Warning
	return warnings
}

func checkCommentFormatting(ctx *CheckContext) []Warning {
	var warnings []Warning
	for _, cg := range ctx.File.Comments {
		for _, c := range cg.List {
			text := c.Text
			if strings.HasPrefix(text, "//") && !strings.HasPrefix(text, "///") && !strings.HasPrefix(text, "//go:") && !strings.HasPrefix(text, "//nolint") && !strings.HasPrefix(text, "//cgo") && !strings.HasPrefix(text, "//export") {
				if len(text) > 2 && text[2] != ' ' && text[2] != '\t' && text[2] != '\n' {
					warnings = append(warnings, addWarn(ctx, c.Pos(), "commentFormatting", "put a space between `//` and comment text"))
				}
			}
		}
	}
	return warnings
}

func checkDefaultCaseOrder(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok || sw.Body == nil {
			return true
		}
		cases := sw.Body.List
		if len(cases) <= 2 {
			return true
		}
		for i, stmt := range cases {
			cc, ok := stmt.(*ast.CaseClause)
			if ok && cc.List == nil { // default case
				if i != 0 && i != len(cases)-1 {
					warnings = append(warnings, addWarn(ctx, cc.Pos(), "defaultCaseOrder", "consider to make `default` case as first or as last case"))
				}
			}
		}
		return true
	})
	return warnings
}

var deprecatedRegex = regexp.compile("(?i)//\\s*deprecated:")

func checkDeprecatedComment(ctx *CheckContext) []Warning {
	var warnings []Warning
	for _, cg := range ctx.File.Comments {
		for _, c := range cg.List {
			text := c.Text
			if strings.HasPrefix(text, "//") && strings.Contains(text, "deprecated:") && !strings.Contains(text, "Deprecated:") {
				warnings = append(warnings, addWarn(ctx, c.Pos(), "deprecatedComment", "use `Deprecated: ` (note the casing) instead of `deprecated: `"))
			}
		}
	}
	return warnings
}

func checkDupArg(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 2 {
			return true
		}
		if equalExpr(call.Args[0], call.Args[1]) {
			fnStr := renderNode(ctx.Fset, call.Fun)
			if fnStr == "bytes.Equal" || fnStr == "reflect.DeepEqual" || fnStr == "copy" {
				callStr := renderNode(ctx.Fset, call)
				warnings = append(warnings, addWarn(ctx, call.Pos(), "dupArg", fmt.Sprintf("suspicious duplicated args in %s", callStr)))
			}
		}
		return true
	})
	return warnings
}

func checkDupBranchBody(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || ifStmt.Else == nil {
			return true
		}
		elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		body1 := renderNode(ctx.Fset, ifStmt.Body)
		body2 := renderNode(ctx.Fset, elseBlock)
		if body1 == body2 {
			warnings = append(warnings, addWarn(ctx, ifStmt.Pos(), "dupBranchBody", "both branches in if statement have same body"))
		}
		return true
	})
	return warnings
}

func checkDupCase(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok || sw.Body == nil {
			return true
		}
		seen := make(map[string]bool)
		for _, stmt := range sw.Body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok || cc.List == nil {
				continue
			}
			for _, expr := range cc.List {
				exprStr := renderNode(ctx.Fset, expr)
				if seen[exprStr] {
					warnings = append(warnings, addWarn(ctx, expr.Pos(), "dupCase", fmt.Sprintf("'%s' is duplicated", renderNode(ctx.Fset, cc))))
				}
				seen[exprStr] = true
			}
		}
		return true
	})
	return warnings
}

func checkDupSubExpr(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		ops := map[token.Token]bool{
			token.EQL: true, token.NEQ: true, token.SUB: true, token.QUO: true,
			token.LAND: true, token.LOR: true, token.AND: true, token.OR: true, token.XOR: true,
		}
		if ops[bin.Op] && equalExpr(bin.X, bin.Y) {
			warnings = append(warnings, addWarn(ctx, bin.Pos(), "dupSubExpr", fmt.Sprintf("suspicious identical LHS and RHS for `%s` operator", bin.Op.String())))
		}
		return true
	})
	return warnings
}

func checkElseif(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || ifStmt.Else == nil {
			return true
		}
		elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok || len(elseBlock.List) != 1 {
			return true
		}
		innerIf, ok := elseBlock.List[0].(*ast.IfStmt)
		if !ok {
			return true
		}
		condStr := renderNode(ctx.Fset, innerIf.Cond)
		warnings = append(warnings, addWarn(ctx, elseBlock.Pos(), "elseif", fmt.Sprintf("can replace 'else {if cond {}}' with 'else if %s {}'", condStr)))
		return true
	})
	return warnings
}

func checkExitAfterDefer(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			return true
		}
		hasDefer := false
		var deferNode ast.Node
		for _, stmt := range fn.Body.List {
			if _, ok := stmt.(*ast.DeferStmt); ok {
				hasDefer = true
				deferNode = stmt
			} else if hasDefer {
				if exprStmt, ok := stmt.(*ast.ExprStmt); ok {
					if call, ok := exprStmt.X.(*ast.CallExpr); ok {
						fnStr := renderNode(ctx.Fset, call.Fun)
						if fnStr == "os.Exit" || fnStr == "log.Fatal" || fnStr == "log.Fatalf" {
							deferStr := renderNode(ctx.Fset, deferNode)
							warnings = append(warnings, addWarn(ctx, stmt.Pos(), "exitAfterDefer", fmt.Sprintf("%s will exit, and `%s` will not run", fnStr, deferStr)))
						}
					}
				}
			}
		}
		return true
	})
	return warnings
}

func checkFlagDeref(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		star, ok := n.(*ast.StarExpr)
		if !ok {
			return true
		}
		call, ok := star.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		fnStr := renderNode(ctx.Fset, call.Fun)
		if strings.HasPrefix(fnStr, "flag.") {
			callStr := renderNode(ctx.Fset, call)
			varType := strings.TrimPrefix(fnStr, "flag.")
			warnings = append(warnings, addWarn(ctx, star.Pos(), "flagDeref", fmt.Sprintf("immediate deref in *%s is most likely an error; consider using flag.%sVar", callStr, varType)))
		}
		return true
	})
	return warnings
}

func checkFlagName(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) == 0 {
			return true
		}
		fnStr := renderNode(ctx.Fset, call.Fun)
		if strings.HasPrefix(fnStr, "flag.") {
			if lit, ok := call.Args[0].(*ast.BasicLit); ok && lit.Kind == token.STRING {
				val := strings.Trim(lit.Value, "\"")
				if strings.HasPrefix(val, "-") {
					warnings = append(warnings, addWarn(ctx, lit.Pos(), "flagName", fmt.Sprintf("flag name \"%s\" should not start with a hyphen", val)))
				}
			}
		}
		return true
	})
	return warnings
}

func checkIfElseChain(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		chainLen := 1
		curr := ifStmt
		for curr.Else != nil {
			if elseIf, ok := curr.Else.(*ast.IfStmt); ok {
				chainLen++
				curr = elseIf
			} else {
				break
			}
		}
		if chainLen > ctx.IfElseChainMinThreshold {
			warnings = append(warnings, addWarn(ctx, ifStmt.Pos(), "ifElseChain", "rewrite if-else to switch statement"))
		}
		return true
	})
	return warnings
}

func checkMapKey(ctx *CheckContext) []Warning {
	var warnings []Warning
	return warnings
}

func checkNewDeref(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		star, ok := n.(*ast.StarExpr)
		if !ok {
			return true
		}
		call, ok := star.X.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		if ident, ok := call.Fun.(*ast.Ident); ok && ident.Name == "new" {
			typeStr := renderNode(ctx.Fset, call.Args[0])
			replacement := typeStr + "{}"
			if typeStr == "int" || typeStr == "int64" || typeStr == "float64" {
				replacement = "0"
			} else if typeStr == "string" {
				replacement = `""`
			} else if typeStr == "bool" {
				replacement = "false"
			}
			warnings = append(warnings, addWarn(ctx, star.Pos(), "newDeref", fmt.Sprintf("replace `*new(%s)` with `%s`", typeStr, replacement)))
		}
		return true
	})
	return warnings
}

func checkOffBy1(ctx *CheckContext) []Warning {
	var warnings []Warning
	return warnings
}

func checkRangeExprCopy(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		rng, ok := n.(*ast.RangeStmt)
		if !ok {
			return true
		}
		if ctx.TypeInfo != nil {
			tv, ok := ctx.TypeInfo.Types[rng.X]
			if ok && tv.Type != nil {
				if arr, ok := tv.Type.Underlying().(*types.Array); ok {
					size := arr.Len() * int(arr.Elem().Underlying().(*types.Basic).Kind()) // rough size estimate
					if arr.Len() > 0 && size >= int64(ctx.RangeExprCopySizeThreshold) {
						exprStr := renderNode(ctx.Fset, rng.X)
						warnings = append(warnings, addWarn(ctx, rng.Pos(), "rangeExprCopy", fmt.Sprintf("copy of %s (%d bytes) can be avoided with &%s", exprStr, size, exprStr)))
					}
				}
			}
		}
		return true
	})
	return warnings
}

func checkSingleCaseSwitch(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok || sw.Body == nil {
			return true
		}
		if len(sw.Body.List) == 1 {
			warnings = append(warnings, addWarn(ctx, sw.Pos(), "singleCaseSwitch", "should rewrite switch statement to if statement"))
		}
		return true
	})
	return warnings
}

func checkSloppyLen(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		call, ok := bin.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		if ident, ok := call.Fun.(*ast.Ident); ok && ident.Name == "len" {
			if lit, ok := bin.Y.(*ast.BasicLit); ok && lit.Value == "0" {
				if bin.Op == token.GTE {
					exprStr := renderNode(ctx.Fset, bin)
					warnings = append(warnings, addWarn(ctx, bin.Pos(), "sloppyLen", fmt.Sprintf("%s is always true", exprStr)))
				}
			}
		}
		return true
	})
	return warnings
}

func checkSwitchTrue(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok || sw.Tag == nil || sw.Init != nil {
			return true
		}
		if ident, ok := sw.Tag.(*ast.Ident); ok && ident.Name == "true" {
			warnings = append(warnings, addWarn(ctx, sw.Pos(), "switchTrue", "replace 'switch true {}' with 'switch {}'"))
		}
		return true
	})
	return warnings
}

func checkUnderef(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		sel, ok := n.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		paren, ok := sel.X.(*ast.ParenExpr)
		if !ok {
			return true
		}
		star, ok := paren.X.(*ast.StarExpr)
		if !ok {
			return true
		}
		xStr := renderNode(ctx.Fset, star.X)
		warnings = append(warnings, addWarn(ctx, sel.Pos(), "underef", fmt.Sprintf("could simplify (*%s).%s to %s.%s", xStr, sel.Sel.Name, xStr, sel.Sel.Name)))
		return true
	})
	return warnings
}

func checkUnlambda(ctx *CheckContext) []Warning {
	var warnings []Warning
	return warnings
}

func checkUnslice(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		slice, ok := n.(*ast.SliceExpr)
		if !ok || slice.Low != nil || slice.High != nil || slice.Max != nil {
			return true
		}
		xStr := renderNode(ctx.Fset, slice.X)
		warnings = append(warnings, addWarn(ctx, slice.Pos(), "unslice", fmt.Sprintf("could simplify %s[:] to %s", xStr, xStr)))
		return true
	})
	return warnings
}

func checkValSwap(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok || len(block.List) < 3 {
			return true
		}
		for i := 0; i <= len(block.List)-3; i++ {
			s1, ok1 := block.List[i].(*ast.AssignStmt)
			s2, ok2 := block.List[i+1].(*ast.AssignStmt)
			s3, ok3 := block.List[i+2].(*ast.AssignStmt)
			if !ok1 || !ok2 || !ok3 {
				continue
			}
			if len(s1.Lhs) == 1 && len(s1.Rhs) == 1 && len(s2.Lhs) == 1 && len(s2.Rhs) == 1 && len(s3.Lhs) == 1 && len(s3.Rhs) == 1 {
				tmp := renderNode(ctx.Fset, s1.Lhs[0])
				a := renderNode(ctx.Fset, s1.Rhs[0])
				b := renderNode(ctx.Fset, s2.Rhs[0])
				if renderNode(ctx.Fset, s2.Lhs[0]) == a && renderNode(ctx.Fset, s3.Lhs[0]) == b && renderNode(ctx.Fset, s3.Rhs[0]) == tmp {
					warnings = append(warnings, addWarn(ctx, s1.Pos(), "valSwap", fmt.Sprintf("can re-write as `%s, %s = %s, %s`", a, b, b, a)))
				}
			}
		}
		return true
	})
	return warnings
}

func checkWrapperFunc(ctx *CheckContext) []Warning {
	var warnings []Warning
	return warnings
}

