func checkCaptLocal(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Type == nil {
			return true
		}
		checkFieldList := func(fields *ast.FieldList) {
			if fields == nil {
				return
			}
			for _, field := range fields.List {
				for _, name := range field.Names {
					if name.Name != "" && name.Name[0] >= 'A' && name.Name[0] <= 'Z' {
						warnings = append(warnings, addWarn(ctx, name.Pos(), "captLocal", fmt.Sprintf("`%s' should not be capitalized", name.Name)))
					}
				}
			}
		}
		checkFieldList(fn.Type.Params)
		checkFieldList(fn.Type.Results)
		return true
	})
	return warnings
}

func checkCaseOrder(ctx *CheckContext) []Warning {
	var warnings []Warning
