func checkIfElseChain(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		chainLen := 1
		curr := ifStmt
		for curr.Else != nil {
			if elseIf, ok := curr.Else.(*ast.IfStmt); ok {
				chainLen++
				curr = elseIf
			} else {
				break
			}
		}
		if chainLen > ctx.IfElseChainMinThreshold {
			warnings = append(warnings, addWarn(ctx, ifStmt.Pos(), "ifElseChain", "rewrite if-else to switch statement"))
		}
		return true
	})
	return warnings
}

