func checkNewDeref(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		star, ok := n.(*ast.StarExpr)
		if !ok {
			return true
		}
		call, ok := star.X.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		if ident, ok := call.Fun.(*ast.Ident); ok && ident.Name == "new" {
			typeStr := renderNode(ctx.Fset, call.Args[0])
			replacement := typeStr + "{}"
			if typeStr == "int" || typeStr == "int64" || typeStr == "float64" {
				replacement = "0"
			} else if typeStr == "string" {
				replacement = `""`
			} else if typeStr == "bool" {
				replacement = "false"
			}
			warnings = append(warnings, addWarn(ctx, star.Pos(), "newDeref", fmt.Sprintf("replace `*new(%s)` with `%s`", typeStr, replacement)))
		}
		return true
	})
	return warnings
