	_ = fs.String("@ruleguard.debug", "", "enable debug for the specified named rules group")
	_ = fs.String("@ruleguard.disable", "", "comma-separated list of disabled groups or skip empty to enable everything")
	_ = fs.String("@ruleguard.enable", "<all>", "comma-separated list of enabled groups or skip empty to enable everything")
	_ = fs.String("@ruleguard.failOn", "", "Determines the behavior when an error occurs while parsing ruleguard files.\nIf flag is not set, log error and skip rule files that contain an error.\nIf flag is set, the value must be a comma-separated list of error conditions.\n* 'import': rule refers to a package that cannot be loaded.\n* 'dsl':    gorule file does not comply with the ruleguard DSL.")
	_ = fs.Bool("@ruleguard.failOnError", false, "deprecated, use failOn param; if set to true, identical to failOn='all', otherwise failOn=''")
	_ = fs.String("@ruleguard.rules", "", "comma-separated list of gorule file paths. Glob patterns such as 'rules-*.go' may be specified")
	_ = fs.Int("@tooManyResultsChecker.maxResults", 5, "maximum number of results")
	_ = fs.Bool("@truncateCmp.skipArchDependent", true, "whether to skip int/uint/uintptr types")
	_ = fs.Bool("@underef.skipRecvDeref", true, "whether to skip (*x).method() calls where x is a pointer receiver")
	_ = fs.Bool("@unnamedResult.checkExported", false, "whether to check exported functions")
	checkGenerated := fs.Bool("checkGenerated", false, "whether to check generated files")
	checkTests := fs.Bool("checkTests", true, "whether to check test files")
	_ = fs.Int("concurrency", 64, "how many concurrent checkers to run (default is runtime.GOMAXPROCS(0))")
	_ = fs.String("cpuprofile", "", "write CPU profile to the specified file")
	disable := fs.String("disable", "", "comma-separated list of checkers to be disabled. Can include #tags")
	enable := fs.String("enable", "appendAssign,argOrder,assignOp,badCall,badCond,captLocal,caseOrder,codegenComment,commentFormatting,defaultCaseOrder,deprecatedComment,dupArg,dupBranchBody,dupCase,dupSubExpr,elseif,exitAfterDefer,flagDeref,flagName,ifElseChain,mapKey,newDeref,offBy1,regexpMust,singleCaseSwitch,sloppyLen,sloppyTypeAssert,switchTrue,typeSwitchVar,underef,unlambda,unslice,valSwap,wrapperFunc", "comma-separated list of enabled checkers. Can include #tags")
	enableAll := fs.Bool("enableAll", false, "identical to -enable with all checkers listed. If true, -enable is ignored")
	exitCode := fs.Int("exitCode", 1, "exit code to be used when lint issues are found")
	_ = fs.String("go", "", "select the Go version to target. Leave as string for the latest")
	_ = fs.String("memprofile", "", "write memory profile to the specified file")
	shorterErrLocation := fs.Bool("shorterErrLocation", true, "whether to replace error location prefix with $GOROOT and $GOPATH")
	verbose := fs.Bool("v", false, "whether to print output useful during linter debugging")

	err := fs.Parse(args)
	if err != nil {
		fmt.Fprint(os.Stderr, buf.String())
		fmt.Fprintf(os.Stderr, "parse args: %v\n", err)
		os.Exit(1)
	}

	enabledMap := make(map[string]bool)
	if *enableAll {
		for name := range checkersDoc {
			enabledMap[name] = true
		}
	} else if *enable != "" {
		for _, item := range strings.Split(*enable, ",") {
			item = strings.TrimSpace(item)
			if strings.HasPrefix(item, "#") {
				tag := item[1:]
				for name, info := range checkersDoc {
					for _, t := range info.Tags {
						if t == tag {
							enabledMap[name] = true
							break
						}
					}
				}
			} else if item != "" {
				enabledMap[item] = true
			}
		}
	}

	if *disable != "" {
		for _, item := range strings.Split(*disable, ",") {
			item = strings.TrimSpace(item)
			if strings.HasPrefix(item, "#") {
				tag := item[1:]
				for name, info := range checkersDoc {
					for _, t := range info.Tags {
						if t == tag {
							delete(enabledMap, name)
							break
						}
					}
				}
			} else if item != "" {
				delete(enabledMap, item)
			}
		}
	}

	if *verbose {
		var allNames []string
		for name := range checkersDoc {
			allNames = append(allNames, name)
		}
		sort.Strings(allNames)
		for _, name := range allNames {
			if enabledMap[name] {
				fmt.Fprintf(os.Stderr, "\tdebug: %s is enabled\n", name)
			} else {
				fmt.Fprintf(os.Stderr, "\tdebug: %s: not enabled by name or tag (-enable)\n", name)
			}
		}
	}

	if len(enabledMap) == 0 {
		fmt.Fprintln(os.Stderr, "init checkers: empty checkers set selected")
		os.Exit(1)
	}

	targets := fs.Args()
	if len(targets) == 0 {
		os.Exit(0)
	}

	files := collectFiles(targets, *checkTests)
	if len(files) == 0 {
		os.Exit(0)
	}

	cwd, _ := os.Getwd()

	var allWarnings []Warning
	genRegex := regexp.MustCompile(`(?i)code generated by.*do not edit`)

	for _, path := range files {
		fset := token.NewFileSet()
		node, parseErr := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if parseErr != nil {
			continue
		}

		if !*checkGenerated {
			isGenerated := false
			for _, cg := range node.Comments {
				if genRegex.MatchString(cg.Text()) {
					isGenerated = true
					break
				}
			}
			if isGenerated {
				continue
			}
		}

		conf := types.Config{
			Importer: importer.Default(),
			Error:    func(error) {},
		}
		typeInfo := &types.Info{
			Types:      make(map[ast.Expr]types.TypeAndValue),
			Defs:       make(map[*ast.Ident]types.Object),
			Uses:       make(map[*ast.Ident]types.Object),
			Selections: make(map[*ast.SelectorExpr]*types.Selection),
		}
		conf.Check(node.Name.Name, fset, []*ast.File{node}, typeInfo)

		displayPath := path
		if *shorterErrLocation {
			if rel, err := filepath.Rel(cwd, path); err == nil {
				if !strings.HasPrefix(rel, "..") {
					if filepath.Dir(rel) == "." {
						displayPath = "./" + filepath.Base(rel)
					} else {
						displayPath = rel
					}
				}
			}
		}

		ctx := &CheckContext{
			Fset:                      fset,
			File:                      node,
			FilePath:                  displayPath,
			TypeInfo:                  typeInfo,
			CaptLocalParamsOnly:       *captLocalParamsOnly,
			CommentedOutCodeMinLength: *commentedOutCodeMinLength,
			ElseifSkipBalanced:        *elseifSkipBalanced,
			HugeParamSizeThreshold:    *hugeParamSizeThreshold,
			IfElseChainMinThreshold:   *ifElseChainMinThreshold,
			NestingReduceBodyWidth:    *nestingReduceBodyWidth,
			RangeExprCopySizeThreshold: *rangeExprCopySizeThreshold,
			RangeValCopySizeThreshold: *rangeValCopySizeThreshold,
			RangeExprCopySkipTestFuncs: *rangeExprCopySkipTestFuncs,
			RangeValCopySkipTestFuncs: *rangeValCopySkipTestFuncs,
		}

		for chName := range enabledMap {
			if fn, ok := checkerRegistry[chName]; ok {
				warns := fn(ctx)
				allWarnings = append(allWarnings, warns...)
			}
		}
	}

	sort.Slice(allWarnings, func(i, j int) bool {
		if allWarnings[i].FilePath != allWarnings[j].FilePath {
			return allWarnings[i].FilePath < allWarnings[j].FilePath
		}
		if allWarnings[i].Line != allWarnings[j].Line {
			return allWarnings[i].Line < allWarnings[j].Line
		}
		if allWarnings[i].Column != allWarnings[j].Column {
			return allWarnings[i].Column < allWarnings[j].Column
		}
		if allWarnings[i].Checker != allWarnings[j].Checker {
			return allWarnings[i].Checker < allWarnings[j].Checker
		}
		return allWarnings[i].Message < allWarnings[j].Message
	})

	for _, w := range allWarnings {
		fmt.Fprintf(os.Stderr, "%s:%d:%d: %s: %s\n", w.FilePath, w.Line, w.Column, w.Checker, w.Message)
	}

	if len(allWarnings) > 0 {
		os.Exit(*exitCode)
	}
	os.Exit(0)
}

func collectFiles(targets []string, checkTests bool) []string {
	var fileList []string
	seen := make(map[string]bool)

	for _, target := range targets {
		isRecursive := strings.HasSuffix(target, "/...") || target == "./..."
		baseDir := strings.TrimSuffix(target, "/...")

		info, err := os.Stat(baseDir)
		if err != nil {
			// check if it's a file path
			if strings.HasSuffix(target, ".go") {
				if !seen[target] {
					seen[target] = true
					fileList = append(fileList, target)
				}
			}
			continue
		}

		if info.IsDir() {
			if isRecursive {
				filepath.Walk(baseDir, func(p string, fi os.FileInfo, err error) error {
					if err == nil && !fi.IsDir() && strings.HasSuffix(p, ".go") {
						if !checkTests && strings.HasSuffix(p, "_test.go") {
							return nil
						}
						if !seen[p] {
							seen[p] = true
							fileList = append(fileList, p)
						}
					}
					return nil
				})
			} else {
				entries, _ := os.ReadDir(baseDir)
				for _, entry := range entries {
					if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".go") {
						p := filepath.Join(baseDir, entry.Name())
						if !checkTests && strings.HasSuffix(p, "_test.go") {
							continue
						}
						if !seen[p] {
							seen[p] = true
							fileList = append(fileList, p)
						}
					}
				}
			}
		} else if strings.HasSuffix(baseDir, ".go") {
			if !checkTests && strings.HasSuffix(baseDir, "_test.go") {
				continue
			}
			if !seen[baseDir] {
				seen[baseDir] = true
				fileList = append(fileList, baseDir)
			}
		}
	}

	return fileList
}

