		if *shorterErrLocation {
			if rel, err := filepath.Rel(cwd, path); err == nil {
				if !strings.HasPrefix(rel, "..") {
					if filepath.Dir(rel) == "." {
						displayPath = "./" + filepath.Base(rel)
					} else {
						displayPath = rel
					}
				}
			}
		}

		ctx := &CheckContext{
			Fset:                      fset,
			File:                      node,
			FilePath:                  displayPath,
			TypeInfo:                  typeInfo,
			CaptLocalParamsOnly:       *captLocalParamsOnly,
			CommentedOutCodeMinLength: *commentedOutCodeMinLength,
			ElseifSkipBalanced:        *elseifSkipBalanced,
			HugeParamSizeThreshold:    *hugeParamSizeThreshold,
			IfElseChainMinThreshold:   *ifElseChainMinThreshold,
			NestingReduceBodyWidth:    *nestingReduceBodyWidth,
			RangeExprCopySizeThreshold: *rangeExprCopySizeThreshold,
			RangeValCopySizeThreshold: *rangeValCopySizeThreshold,
			RangeExprCopySkipTestFuncs: *rangeExprCopySkipTestFuncs,
			RangeValCopySkipTestFuncs: *rangeValCopySkipTestFuncs,
		}

		for chName := range enabledMap {
			if fn, ok := checkerRegistry[chName]; ok {
				warns := fn(ctx)
				allWarnings = append(allWarnings, warns...)
			}
		}
	}

	sort.Slice(allWarnings, func(i, j int) bool {
		if allWarnings[i].FilePath != allWarnings[j].FilePath {
			return allWarnings[i].FilePath < allWarnings[j].FilePath
		}
		if allWarnings[i].Line != allWarnings[j].Line {
			return allWarnings[i].Line < allWarnings[j].Line
		}
		if allWarnings[i].Column != allWarnings[j].Column {
			return allWarnings[i].Column < allWarnings[j].Column
		}
		if allWarnings[i].Checker != allWarnings[j].Checker {
			return allWarnings[i].Checker < allWarnings[j].Checker
		}
		return allWarnings[i].Message < allWarnings[j].Message
	})

	for _, w := range allWarnings {
		fmt.Fprintf(os.Stderr, "%s:%d:%d: %s: %s\n", w.FilePath, w.Line, w.Column, w.Checker, w.Message)
	}

	if len(allWarnings) > 0 {
		os.Exit(*exitCode)
	}
	os.Exit(0)
}

func collectFiles(targets []string, checkTests bool) []string {
	var fileList []string
	seen := make(map[string]bool)

	for _, target := range targets {
		isRecursive := strings.HasSuffix(target, "/...") || target == "./..."
		baseDir := strings.TrimSuffix(target, "/...")

		info, err := os.Stat(baseDir)
		if err != nil {
			// check if it's a file path
			if strings.HasSuffix(target, ".go") {
				if !seen[target] {
					seen[target] = true
					fileList = append(fileList, target)
				}
			}
			continue
		}

		if info.IsDir() {
			if isRecursive {
				filepath.Walk(baseDir, func(p string, fi os.FileInfo, err error) error {
					if err == nil && !fi.IsDir() && strings.HasSuffix(p, ".go") {
						if !checkTests && strings.HasSuffix(p, "_test.go") {
							return nil
						}
						if !seen[p] {
							seen[p] = true
							fileList = append(fileList, p)
						}
					}
					return nil
				})
			} else {
				entries, _ := os.ReadDir(baseDir)
				for _, entry := range entries {
					if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".go") {
						p := filepath.Join(baseDir, entry.Name())
						if !checkTests && strings.HasSuffix(p, "_test.go") {
							continue
						}
						if !seen[p] {
							seen[p] = true
							fileList = append(fileList, p)
						}
					}
				}
			}
		} else if strings.HasSuffix(baseDir, ".go") {
			if !checkTests && strings.HasSuffix(baseDir, "_test.go") {
				continue
			}
			if !seen[baseDir] {
				seen[baseDir] = true
				fileList = append(fileList, baseDir)
			}
		}
	}

	return fileList
}

