func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func levDistance(a, b string) int {
	la, lb := len(a), len(b)
	d := make([][]int, la+1)
	for i := range d {
		d[i] = make([]int, lb+1)
		d[i][0] = i
	}
	for j := range d[0] {
		d[0][j] = j
	}
	for i := 1; i <= la; i++ {
		for j := 1; j <= lb; j++ {
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}
			d[i][j] = minInt(d[i-1][j]+1, minInt(d[i][j-1]+1, d[i-1][j-1]+cost))
		}
	}
	return d[la][lb]
}

func main() {
	args := os.Args[1:]
	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, "no args provided")
		os.Exit(0)
	}

	cmd := args[0]
	switch cmd {
	case "version":
		fmt.Println("go-critic version: v0.0.0-SNAPSHOT\n")
		os.Exit(0)
	case "help":
		printHelp()
		os.Exit(0)
	case "doc":
		runDoc(args[1:])
	case "check":
		runCheck(args[1:])
	default:
		runUnknownCommand(cmd)
	}
}

func printHelp() {
	fmt.Print(`Usage:

    go-critic <command> [arguments...]

The commands are:

    check             run linter over specified targets
    doc               get installed checkers documentation
    help              shows help message
    version           shows version of the application

Version: v0.0.0-SNAPSHOT

`)
