func runUnknownCommand(cmd string) {
	fmt.Fprintf(os.Stderr, "no such command %q\n", cmd)
	cmds := []string{"check", "doc", "help", "version"}
	minDist := 999
	closest := ""
	for _, c := range cmds {
		d := levDistance(cmd, c)
		if d < minDist {
			minDist = d
			closest = c
		}
	}
	if minDist <= 2 {
		fmt.Printf("%q unknown command, did you mean %q?\nRun \"go-critic help\" for usage.\n\n", cmd, closest)
