func renderNode(fset *token.FileSet, n interface{}) string {
	var buf bytes.Buffer
	if err := format.Node(&buf, fset, n); err != nil {
		return ""
	}
	return buf.String()
}

func equalExpr(a, b ast.Expr) bool {
	if a == nil || b == nil {
		return a == b
	}
	switch x := a.(type) {
	case *ast.Ident:
		y, ok := b.(*ast.Ident)
		return ok && x.Name == y.Name
	case *ast.BasicLit:
		y, ok := b.(*ast.BasicLit)
		return ok && x.Kind == y.Kind && x.Value == y.Value
	case *ast.SelectorExpr:
		y, ok := b.(*ast.SelectorExpr)
		return ok && x.Sel.Name == y.Sel.Name && equalExpr(x.X, y.X)
	case *ast.IndexExpr:
		y, ok := b.(*ast.IndexExpr)
		return ok && equalExpr(x.X, y.X) && equalExpr(x.Index, y.Index)
	case *ast.StarExpr:
		y, ok := b.(*ast.StarExpr)
		return ok && equalExpr(x.X, y.X)
	case *ast.UnaryExpr:
		y, ok := b.(*ast.UnaryExpr)
		return ok && x.Op == y.Op && equalExpr(x.X, y.X)
	case *ast.BinaryExpr:
		y, ok := b.(*ast.BinaryExpr)
		return ok && x.Op == y.Op && equalExpr(x.X, y.X) && equalExpr(x.Y, y.Y)
	case *ast.CallExpr:
		y, ok := b.(*ast.CallExpr)
		if !ok || len(x.Args) != len(y.Args) || !equalExpr(x.Fun, y.Fun) {
			return false
		}
		for i := range x.Args {
			if !equalExpr(x.Args[i], y.Args[i]) {
				return false
			}
		}
		return true
	case *ast.ParenExpr:
		return equalExpr(x.X, b)
	}
	return false
}

func addWarn(ctx *CheckContext, pos token.Pos, checker, msg string) Warning {
	position := ctx.Fset.Position(pos)
	return Warning{
		FilePath: ctx.FilePath,
		Line:     position.Line,
		Column:   position.Column,
		Checker:  checker,
		Message:  msg,
	}
}

func checkAppendAssign(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		stmt, ok := n.(*ast.AssignStmt)
		if !ok || len(stmt.Lhs) != 1 || len(stmt.Rhs) != 1 {
			return true
		}
		call, ok := stmt.Rhs[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		ident, ok := call.Fun.(*ast.Ident)
		if !ok || ident.Name != "append" || len(call.Args) == 0 {
			return true
		}
		if !equalExpr(stmt.Lhs[0], call.Args[0]) {
			warnings = append(warnings, addWarn(ctx, call.Pos(), "appendAssign", "append result not assigned to the same slice"))
		}
		return true
	})
	return warnings
}

func checkArgOrder(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 2 {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		pkgIdent, ok := sel.X.(*ast.Ident)
		if !ok || pkgIdent.Name != "strings" {
			return true
		}
		fn := sel.Sel.Name
		if fn == "HasPrefix" || fn == "HasSuffix" || fn == "Contains" {
			_, firstLit := call.Args[0].(*ast.BasicLit)
			_, secondLit := call.Args[1].(*ast.BasicLit)
			if firstLit && !secondLit {
				arg0 := renderNode(ctx.Fset, call.Args[0])
				arg1 := renderNode(ctx.Fset, call.Args[1])
				warnings = append(warnings, addWarn(ctx, call.Pos(), "argOrder", fmt.Sprintf("%s and %s arguments order looks reversed", arg0, arg1)))
			}
		}
		return true
	})
	return warnings
}

func checkAssignOp(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		stmt, ok := n.(*ast.AssignStmt)
		if !ok || stmt.Tok != token.ASSIGN || len(stmt.Lhs) != 1 || len(stmt.Rhs) != 1 {
			return true
		}
		bin, ok := stmt.Rhs[0].(*ast.BinaryExpr)
		if !ok {
			return true
		}
		if equalExpr(stmt.Lhs[0], bin.X) {
			xStr := renderNode(ctx.Fset, stmt.Lhs[0])
			yStr := renderNode(ctx.Fset, bin.Y)
			if bin.Op == token.ADD && yStr == "1" {
				warnings = append(warnings, addWarn(ctx, stmt.Pos(), "assignOp", fmt.Sprintf("replace `%s = %s + 1` with `%s++`", xStr, xStr, xStr)))
			} else {
				opStr := bin.Op.String()
				warnings = append(warnings, addWarn(ctx, stmt.Pos(), "assignOp", fmt.Sprintf("replace `%s = %s %s %s` with `%s %s= %s`", xStr, xStr, opStr, yStr, xStr, opStr, yStr)))
			}
		}
		return true
	})
	return warnings
}

func checkBadCall(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 4 {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		pkgIdent, ok := sel.X.(*ast.Ident)
		if !ok || (pkgIdent.Name != "strings" && pkgIdent.Name != "bytes") {
			return true
		}
		if sel.Sel.Name == "Replace" {
			if lit, ok := call.Args[3].(*ast.BasicLit); ok && lit.Value == "0" {
				position := ctx.Fset.Position(call.Args[3].Pos())
				warnings = append(warnings, Warning{
					FilePath: ctx.FilePath,
					Line:     position.Line,
					Column:   position.Column,
					Checker:  "badCall",
					Message:  "suspicious arg 0, probably meant -1",
				})
			}
		}
		return true
	})
	return warnings
}

