func checkCommentFormatting(ctx *CheckContext) []Warning {
	var warnings []Warning
	for _, cg := range ctx.File.Comments {
		for _, c := range cg.List {
			text := c.Text
			if strings.HasPrefix(text, "//") && !strings.HasPrefix(text, "///") && !strings.HasPrefix(text, "//go:") && !strings.HasPrefix(text, "//nolint") && !strings.HasPrefix(text, "//cgo") && !strings.HasPrefix(text, "//export") {
				if len(text) > 2 && text[2] != ' ' && text[2] != '\t' && text[2] != '\n' {
					warnings = append(warnings, addWarn(ctx, c.Pos(), "commentFormatting", "put a space between `//` and comment text"))
				}
			}
		}
	}
	return warnings
}

func checkDefaultCaseOrder(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok || sw.Body == nil {
			return true
		}
		cases := sw.Body.List
		if len(cases) <= 2 {
			return true
		}
		for i, stmt := range cases {
			cc, ok := stmt.(*ast.CaseClause)
			if ok && cc.List == nil { // default case
				if i != 0 && i != len(cases)-1 {
					warnings = append(warnings, addWarn(ctx, cc.Pos(), "defaultCaseOrder", "consider to make `default` case as first or as last case"))
				}
			}
		}
		return true
	})
	return warnings
}

var deprecatedRegex = regexp.MustCompile(`(?i)//\s*deprecated:`)

func checkDeprecatedComment(ctx *CheckContext) []Warning {
	var warnings []Warning
	for _, cg := range ctx.File.Comments {
		for _, c := range cg.List {
			text := c.Text
			if strings.HasPrefix(text, "//") && strings.Contains(text, "deprecated:") && !strings.Contains(text, "Deprecated:") {
				warnings = append(warnings, addWarn(ctx, c.Pos(), "deprecatedComment", "use `Deprecated: ` (note the casing) instead of `deprecated: `"))
			}
		}
	}
	return warnings
}

func checkDupArg(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 2 {
			return true
		}
		if equalExpr(call.Args[0], call.Args[1]) {
			fnStr := renderNode(ctx.Fset, call.Fun)
			if fnStr == "bytes.Equal" || fnStr == "reflect.DeepEqual" || fnStr == "copy" {
				callStr := renderNode(ctx.Fset, call)
				warnings = append(warnings, addWarn(ctx, call.Pos(), "dupArg", fmt.Sprintf("suspicious duplicated args in %s", callStr)))
			}
		}
		return true
	})
	return warnings
}

func checkDupBranchBody(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || ifStmt.Else == nil {
			return true
		}
		elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		body1 := renderNode(ctx.Fset, ifStmt.Body)
		body2 := renderNode(ctx.Fset, elseBlock)
		if body1 == body2 {
			warnings = append(warnings, addWarn(ctx, ifStmt.Pos(), "dupBranchBody", "both branches in if statement have same body"))
		}
		return true
	})
	return warnings
}

func checkDupCase(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok || sw.Body == nil {
			return true
		}
		seen := make(map[string]bool)
		for _, stmt := range sw.Body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok || cc.List == nil {
				continue
			}
			for _, expr := range cc.List {
				exprStr := renderNode(ctx.Fset, expr)
				if seen[exprStr] {
					warnings = append(warnings, addWarn(ctx, expr.Pos(), "dupCase", fmt.Sprintf("'%s' is duplicated", renderNode(ctx.Fset, cc))))
				}
				seen[exprStr] = true
			}
		}
		return true
	})
	return warnings
}

func checkDupSubExpr(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		ops := map[token.Token]bool{
			token.EQL: true, token.NEQ: true, token.SUB: true, token.QUO: true,
			token.LAND: true, token.LOR: true, token.AND: true, token.OR: true, token.XOR: true,
		}
		if ops[bin.Op] && equalExpr(bin.X, bin.Y) {
			warnings = append(warnings, addWarn(ctx, bin.Pos(), "dupSubExpr", fmt.Sprintf("suspicious identical LHS and RHS for `%s` operator", bin.Op.String())))
		}
		return true
	})
	return warnings
}

func checkElseif(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || ifStmt.Else == nil {
			return true
		}
		elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok || len(elseBlock.List) != 1 {
			return true
		}
		innerIf, ok := elseBlock.List[0].(*ast.IfStmt)
		if !ok {
			return true
		}
		condStr := renderNode(ctx.Fset, innerIf.Cond)
		warnings = append(warnings, addWarn(ctx, elseBlock.Pos(), "elseif", fmt.Sprintf("can replace 'else {if cond {}}' with 'else if %s {}'", condStr)))
		return true
	})
	return warnings
}

func checkExitAfterDefer(ctx *CheckContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.File, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			return true
		}
		hasDefer := false
		var deferNode ast.Node
		for _, stmt := range fn.Body.List {
			if _, ok := stmt.(*ast.DeferStmt); ok {
				hasDefer = true
				deferNode = stmt
			} else if hasDefer {
				if exprStmt, ok := stmt.(*ast.ExprStmt); ok {
					if call, ok := exprStmt.X.(*ast.CallExpr); ok {
						fnStr := renderNode(ctx.Fset, call.Fun)
						if fnStr == "os.Exit" || fnStr == "log.Fatal" || fnStr == "log.Fatalf" {
							deferStr := renderNode(ctx.Fset, deferNode)
							warnings = append(warnings, addWarn(ctx, stmt.Pos(), "exitAfterDefer", fmt.Sprintf("%s will exit, and `%s` will not run", fnStr, deferStr)))
						}
					}
				}
			}
		}
		return true
	})
	return warnings
}

func checkFlagDeref(ctx *CheckContext) []Warning {
