		if !ok {
			return true
		}
		fnStr := renderNode(ctx.Fset, call.Fun)
		if strings.HasPrefix(fnStr, "flag.") {
			callStr := renderNode(ctx.Fset, call)
			varType := strings.TrimPrefix(fnStr, "flag.")
			warnings = append(warnings, addWarn(ctx, star.Pos(), "flagDeref", fmt.Sprintf("immediate deref in *%s is most likely an error; consider using flag.%sVar", callStr, varType)))
		}
		return true
	})
	return warnings
